mapper.select:
select id, material_id, storage_address, available_qty, locked_qty, total_qty, is_del, create_time, update_time
from material_stock
where material_id = #{materialId}
  and storage_address = #{storageAddress}
  and is_del = 0
limit 1

mapper.update:
update material_stock
set locked_qty = locked_qty - #{outboundQty},
    total_qty = total_qty - #{outboundQty},
    update_time = now()
where id = #{stockId}
  and locked_qty >= #{outboundQty}
  and total_qty >= #{outboundQty}
  and is_del = 0

update material_stock
set available_qty = available_qty - #{outboundQty},
    total_qty = total_qty - #{outboundQty},
    update_time = now()
where id = #{stockId}
  and available_qty >= #{outboundQty}
  and total_qty >= #{outboundQty}
  and is_del = 0
